static bool nalComponentTrackPresent(const nalComponentEnum* componentEnum,
                                     int track)
{
    const nalGeneric::nalGenericAnim* anim =
        (const nalGeneric::nalGenericAnim*)componentEnum->Anim;
    if (track >= anim->Skeleton->PoseTrackCount
        && _tlAssert(
               "c:\\cod\\code\\tl\\nal\\include\\common\\nal_generic.h",
               621, "track < GetSkeleton()->PoseTrackCount",
               "attempt to access an invalid track"))
    {
        __debugbreak();
    }
    return (anim->TrackBitMask[track / 32]
            & (1u << (track & 0x1F))) != 0;
}

template <typename T>
struct nalRLEDecoder {
    const unsigned char* Ptr;
    unsigned char Count;
    T Value;

    void Decode(T* dst, unsigned int stride, unsigned int qty)
    {
        if (qty == 0)
            return;
        do
        {
            if (Count == 0)
            {
                const unsigned char count = *Ptr++;
                Count = count;
                Value = (T)*Ptr++;
                if (count == 0
                    && _tlAssert(
                           "c:\\cod\\code\\tl\\nal\\include\\common\\nal_rle_decoder.h",
                           17, "Count != 0",
                           "shouldn't have any empty counts"))
                {
                    __debugbreak();
                }
            }
            *dst = Value;
            dst = (T*)((char*)dst + stride);
            --Count;
            --qty;
        }
        while (qty != 0);
    }
};

static_assert(sizeof(nalRLEDecoder<unsigned char>) == 8,
              "nalRLEDecoder layout mismatch");

