    xmm1 = axis.z.v;
    xmm3 = _mm_mul_ps(xmm3, xmm1);
    xmm1 = axis.x.v;
    xmm4 = _mm_mul_ps(xmm4, xmm1);
    xmm4 = _mm_add_ps(xmm4, xmm3);
    xmm4 = _mm_add_ps(xmm4, xmm2);
    float out[3];
